.syntax unified
.thumb
.text
.global main_app
.type main_app, %function

.equ RCC_BASE,    0x40023800
.equ RCC_AHB1ENR, 0x30
.equ RCC_APB1ENR, 0x40

.equ GPIOA_BASE,  0x40020000
.equ GPIOD_BASE,  0x40020C00
.equ MODER_OFFSET, 0x00
.equ AFRL_OFFSET,  0x20
.equ ODR_OFFSET,   0x14
.equ IDR_OFFSET,   0x10

.equ USART2_BASE, 0x40004400
.equ USART_SR,    0x00
.equ USART_DR,    0x04
.equ USART_BRR,   0x08
.equ USART_CR1,   0x0C

delay_ms:
    LDR R1, =4000           // assuming 16 MHz clock and 4 cycles per loop, we have 4000 iterations per ms
    MUL R0, R0, R1			// R0 is the function argument
    CMP R0, #0
    BEQ delay_end
delay_loop:
    NOP                     // insert no operations for delay simulation
    SUBS R0, R0, #1
    BNE delay_loop
delay_end:
    BX LR

uart_putc:
    LDR R1, =USART2_BASE		// R0 is the function argument
putc_wait:
    LDR R2, [R1, #USART_SR]
    ANDS R2, R2, #(1<<7)
    BEQ putc_wait           	// pause while UART is busy sending a character (Transmit Data Register Empty = 0)
    STRB R0, [R1, #USART_DR] 	// when it becomes available again, put c in Data Register
    BX LR

uart_puts:                  	// function to print an entire string
    PUSH {R4, LR}				// keep R4 and LR in stack because they will change values
    MOV R4, R0					// R0 is the function argument
puts_loop:
    LDRB R0, [R4], #1			// Byte-wise (character length)
    CMP R0, #0					// while c != '\0' (end of string)
    BEQ puts_end
    BL uart_putc            	// send c to UART
    B puts_loop
puts_end:
    POP {R4, PC}				// return R4 and put LR to PC

uart_putn:                  	// function to appropriately depict numbers
    PUSH {R4-R7, LR}			// keep R4-R7 and LR in stack because they will change values
    MOV R4, R0					// R0 is the function argument
    CMP R4, #0
    BNE putn_calc
    MOV R0, #'0'
    BL uart_putc            	// 0 is depicted as '0' in ASCII, no change
    POP {R4-R7, PC}				// return R4-R7 and put LR to PC
putn_calc:
    LDR R5, =10
    MOV R6, #0					// length counter
    SUB SP, SP, #12         	// temporary buffer in stack
    MOV R7, SP
putn_loop:
    CMP R4, #0
    BEQ putn_print
    UDIV R0, R4, R5         	// R0 = R4 / 10
    MLS R1, R0, R5, R4      	// R1 = R4 - (R0 * 10) (modulo equation)
    ADD R1, R1, #'0'        	// translate all digits of a number to its correct ASCII value, using '0' as position reference
    STRB R1, [R7, R6]
    ADD R6, R6, #1
    MOV R4, R0
    B putn_loop
putn_print:
    CMP R6, #0
    BEQ putn_end			// if length = 0 skip
    SUB R6, R6, #1
    LDRB R0, [R7, R6]
    BL uart_putc            // print them in the correct (reverse) order
    B putn_print
putn_end:
    ADD SP, SP, #12			// empty temporary buffer in stack
    POP {R4-R7, PC}			// return R4-R7 and put LR to PC

get_complement:             // RNA complement calculation, R0 is the function argument
    CMP R0, #'A'
    BNE 1f
    MOV R0, #'U'
    BX LR
1:  CMP R0, #'U'
    BNE 2f
    MOV R0, #'A'
    BX LR
2:  CMP R0, #'G'
    BNE 3f
    MOV R0, #'C'
    BX LR
3:  CMP R0, #'C'
    BNE 4f
    MOV R0, #'G'
    BX LR
4:  MOV R0, #0
    BX LR

main_app:
    PUSH {R4-R11, LR} 	// keep R4-R11 and LR in stack

    LDR R0, =RCC_BASE
    LDR R1, [R0, #RCC_AHB1ENR]
    ORR R1, R1, #((1<<0) | (1<<3))
    STR R1, [R0, #RCC_AHB1ENR] // enable clock for GPIOA, GPIOD

    LDR R1, [R0, #RCC_APB1ENR]
    ORR R1, R1, #(1<<17)
    STR R1, [R0, #RCC_APB1ENR] // enable clock for USART2

    LDR R0, =GPIOA_BASE
    LDR R1, [R0, #MODER_OFFSET]
    LDR R2, =0x0F0F00F0
    BIC R1, R1, R2
    LDR R2, =0x050A00A0
    ORR R1, R1, R2
    STR R1, [R0, #MODER_OFFSET] // set GPIOA PA12, PA13 as outputs, PA2 as TX, PA3 as RX (alternate function)

    LDR R1, [R0, #AFRL_OFFSET]
    LDR R2, =0x00007700
    ORR R1, R1, R2
    STR R1, [R0, #AFRL_OFFSET] // set alternate function 7 for the desired functionality USART2

    LDR R0, =GPIOD_BASE
    LDR R1, [R0, #MODER_OFFSET]
    LDR R2, =(3 << 8)
    BIC R1, R1, R2
    STR R1, [R0, #MODER_OFFSET] // set GPIOD PD4 as input

    LDR R0, =USART2_BASE
    LDR R1, =0x008B
    STR R1, [R0, #USART_BRR] // set appropriate Baud Rate for 16 MHz clock

    LDR R1, =((1<<13) | (1<<3) | (1<<2))
    STR R1, [R0, #USART_CR1] // enable USART enable bit, Transmitter enable bit, Receiver enable bit

// Register Map:
// R4: Input sequence length (idx)
// R5: Search reset flag (1 if PD4 pressed) / Match counter
// R6: Universal iterator (i) / COVID sequence length
// R7: Outer loop iterator (search index)
// R8: Inner loop iterator (pattern match index)
// R9: Match boolean flag (1 if matched, 0 if failed)

main_loop:
    MOV R4, #0              // idx = 0
    MOV R5, #0              // reset_search = 0

    LDR R0, =msg_insert
    BL uart_puts

input_loop:					// PD4 polling instead of iterrupt handling
    LDR R0, =GPIOD_BASE
    LDR R1, [R0, #IDR_OFFSET]
    ANDS R1, R1, #(1<<4)
    BEQ check_uart          // if PD4 is on

    LDR R0, =GPIOA_BASE
    LDR R1, [R0, #ODR_OFFSET]
    ORR R1, R1, #(1<<13)
    STR R1, [R0, #ODR_OFFSET] // turn on PA13

    LDR R0, =3000
    BL delay_ms             // for 3 seconds

    LDR R0, =GPIOA_BASE
    LDR R1, [R0, #ODR_OFFSET]
    BIC R1, R1, #(1<<13)
    STR R1, [R0, #ODR_OFFSET] // and then turn it off

wait_pd4_release:             // wait until it is not pressed (avoid multiple interrupts)
    LDR R0, =GPIOD_BASE
    LDR R1, [R0, #IDR_OFFSET]
    ANDS R1, R1, #(1<<4)
    BNE wait_pd4_release      // do not move on until it is not pressed anymore

    MOV R5, #1              // reset_search = 1
    LDR R0, =msg_reset
    BL uart_puts
    B end_input_loop

check_uart:
    LDR R0, =USART2_BASE
    LDR R1, [R0, #USART_SR]
    ANDS R1, R1, #(1<<5)
    BEQ input_loop          // check for new character in RX

    LDR R0, =USART2_BASE
    LDRB R6, [R0, #USART_DR]

    CMP R6, #'\n'
    BEQ handle_enter
    CMP R6, #'\r'
    BEQ handle_enter
    B check_nucleotides

handle_enter:
    CMP R4, #0
    BGT end_input_loop      // end of sequence
    B input_loop

check_nucleotides:
    CMP R6, #'A'
    BEQ accept_char
    CMP R6, #'U'
    BEQ accept_char
    CMP R6, #'G'
    BEQ accept_char
    CMP R6, #'C'
    BEQ accept_char
    B input_loop

accept_char:
    LDR R0, =input_buf
    STRB R6, [R0, R4]		// R4 is the length counter
    ADD R4, R4, #1
    MOV R0, R6
    BL uart_putc            // if it is accepted, print it
    B input_loop

end_input_loop:
    CMP R5, #1
    BEQ main_loop           // if PD4 was turned on (reset_flag = 1), do not print the accumulated characters

    LDR R0, =input_buf
    MOV R1, #0
    STRB R1, [R0, R4]       // finish the sequence

    LDR R0, =msg_newline
    BL uart_puts            // change line

    MOV R6, #0              // i = 0 for complement loop
comp_loop:
    CMP R6, R4
    BGE end_comp_loop
    LDR R0, =input_buf
    LDRB R0, [R0, R6]
    BL get_complement       // calculate complementary sequence
    LDR R1, =comp_buf
    STRB R0, [R1, R6]
    ADD R6, R6, #1
    B comp_loop
end_comp_loop:
    LDR R0, =comp_buf
    MOV R1, #0
    STRB R1, [R0, R4]       // finish the sequence by inserting null terminator ('\0')

    LDR R0, =msg_comp
    BL uart_puts
    LDR R0, =comp_buf
    BL uart_puts
    LDR R0, =msg_pos
    BL uart_puts

    MOV R5, #0              // count = 0
    MOV R6, #0              // sequence length
strlen_loop:
    LDR R0, =covid_seq
    LDRB R1, [R0, R6]
    CMP R1, #0
    BEQ do_search
    ADD R6, R6, #1
    B strlen_loop

do_search:
    MOV R7, #0              // i = 0
search_outer:
    SUB R1, R6, R4          // sequence length - idx
    CMP R7, R1
    BGT search_end          // find matches in Covid-19 sequence

    MOV R9, #1              // match = 1
    MOV R8, #0              // j = 0
search_inner:
    CMP R8, R4
    BGE inner_end
    LDR R0, =covid_seq
    ADD R1, R7, R8          // i + j
    LDRB R1, [R0, R1]
    LDR R2, =comp_buf
    LDRB R2, [R2, R8]
    CMP R1, R2
    BEQ next_j
    MOV R9, #0
    B inner_end
next_j:
    ADD R8, R8, #1
    B search_inner
inner_end:
    CMP R9, #1
    BNE next_i
    ADD R5, R5, #1
    MOV R0, R7
    BL uart_putn            // keep all of the starting positions, if there are any
    LDR R0, =msg_space
    BL uart_puts
next_i:
    ADD R7, R7, #1
    B search_outer

search_end:
    LDR R0, =msg_total
    BL uart_puts
    MOV R0, R5
    BL uart_putn            // print them
    LDR R0, =msg_newline
    BL uart_puts

    CMP R5, #0
    BLE main_loop           // if there is at least an occurrence

    LDR R0, =GPIOA_BASE
    LDR R1, [R0, #ODR_OFFSET]
    ORR R1, R1, #(1<<12)
    STR R1, [R0, #ODR_OFFSET] // turn on PA12

    LDR R0, =2000
    BL delay_ms               // for 2 seconds

    LDR R0, =GPIOA_BASE
    LDR R1, [R0, #ODR_OFFSET]
    BIC R1, R1, #(1<<12)
    STR R1, [R0, #ODR_OFFSET] // and then close it

    B main_loop

.align 2
msg_insert:  .asciz "Insert RNA sequence: "
msg_reset:   .asciz "\r\n[!] Search Reset by PD4 !\r\n\n"
msg_newline: .asciz "\r\n"
msg_comp:    .asciz "Complement to find: "
msg_pos:     .asciz "\r\nPositions: "
msg_space:   .asciz " "
msg_total:   .asciz "\r\nTotal occurrences: "

.bss
.align 2
input_buf: .space 100
comp_buf:  .space 100

.data
.align 2
covid_seq:
    .asciz ""
